-- The approved editorial template applies to the complete catalogue, including hidden cards.
-- Publication states, descriptions, photos, hours, notices, events and relations are untouched.
-- All headings include EN / VI / RU / ZH / KO / JA, including sections awaiting future media.
BEGIN;

ALTER TABLE public.destinations ALTER COLUMN detail_layout SET DEFAULT 'editorial';
COMMENT ON COLUMN public.destinations.detail_layout IS 'Editorial is the shared expanded-card model for current and future destinations, regardless of publication status.';

UPDATE public.destinations SET detail_layout='editorial' WHERE detail_layout <> 'editorial';

-- Keep existing explicit choices; select a usable published action for remaining cards.
UPDATE public.destinations d SET primary_link_id=(
  SELECT l.id FROM public.destination_links l
  WHERE l.destination_id=d.id AND l.active AND l.kind <> 'INSTAGRAM'
  ORDER BY CASE l.kind WHEN 'BOOK' THEN 0 WHEN 'DISCOVER' THEN 1 WHEN 'WEBSITE' THEN 1 ELSE 2 END,
    l.display_order,l.id LIMIT 1
)
WHERE d.primary_link_id IS NULL;

-- Compact language arrays keep the authored copy readable. Source matching prevents stale
-- translations from being displayed after a marketing editor changes an English heading.
WITH copy AS (
  SELECT value->>'id' AS id, value->'headings' AS headings
  FROM jsonb_array_elements($headings$
