]
$headings$::jsonb)
), localized AS (
  SELECT c.id,c.headings,jsonb_object_agg(locale.code,
    (SELECT jsonb_object_agg(section.key,jsonb_build_object(
      'source',section.value->>0,'value',section.value->>locale.position))
     FROM jsonb_each(c.headings) section)) AS translations
  FROM copy c CROSS JOIN (VALUES ('vi',1),('ru',2),('zh',3),('ko',4),('ja',5)) locale(code,position)
  GROUP BY c.id,c.headings
)
UPDATE public.destinations d SET
  links_heading=l.headings->'links'->>0,
  video_heading=l.headings->'video'->>0,
  instagram_heading=l.headings->'instagram'->>0,
  heading_translations=l.translations
FROM localized l WHERE d.id=l.id;

COMMIT;
